    fn notification(peer_id: &str, characteristic_occurrence: u64, value: Vec<u8>) -> RadioEvent {
        notification_epoch(peer_id, characteristic_occurrence, value, 0)
    }

    fn notification_epoch(
        peer_id: &str,
        characteristic_occurrence: u64,
        value: Vec<u8>,
        epoch: u64,
    ) -> RadioEvent {
        RadioEvent::Notification {
            peer_id: peer_id.to_owned(),
            service_uuid: HRM_SERVICE.to_owned(),
            service_occurrence: 0,
            characteristic_uuid: HRM_MEASUREMENT.to_owned(),
            characteristic_occurrence,
            epoch,
            value,
        }
    }

    #[tokio::test]
    async fn scan_ingests_advertisements_and_cleans_up() {
        let central = open().await;
        central
            .start_scan("owner-a", &[], OpControl::budget_ms(5000))
            .await
            .expect("start scan");
        assert!(central.has_active_scan().await);
        central
            .boundary()
            .push_event(advertisement("peer-1"))
            .expect("synthetic event admission failed");
        wait_peer(&central, "peer-1").await;
        stop_owned_scan(&central).await.expect("stop scan");
        assert!(!central.has_active_scan().await);
        assert!(
            !central.boundary().scan_active(),
            "OS scan stopped on cleanup"
        );
        let calls = central.boundary().calls();
        let start = calls
            .iter()
            .position(|call| call == "start_scan")
            .expect("start recorded");
        let stop = calls
            .iter()
            .position(|call| call == "stop_scan")
            .expect("stop recorded");
        assert!(start < stop, "stop follows start");
        assert_eq!(
            calls.iter().filter(|call| *call == "stop_scan").count(),
            1,
            "cleanup stops the OS scan exactly once"
        );
    }

    #[tokio::test]
    async fn scan_stop_retries_only_the_unfinished_callback_fence() {
        let central = open().await;
        let session = central
            .start_scan("owner-a", &[], OpControl::budget_ms(5000))
            .await
            .expect("start scan");
        central.boundary().fail_next(
            FaultOp::ScanIngressFence,
            "transient callback fence refusal",
        );

        let error = central
            .stop_scan(session.operation_id(), OpControl::budget_ms(5000))
            .await
            .expect_err("fence refusal retains cleanup");
        assert_eq!(error.code_str(), "scan.stop-failed");
        assert!(
            central.has_active_scan().await,
            "fence debt retains scan ownership"
        );

        central
            .stop_scan(session.operation_id(), OpControl::budget_ms(5000))
            .await
            .expect("retry fences the already-retired callback ingress");
        let calls = central.boundary().calls();
        assert_eq!(
            calls.iter().filter(|call| *call == "stop_scan").count(),
            1,
            "physical stop is never repeated after it succeeded"
        );
        assert_eq!(
            calls
                .iter()
                .filter(|call| *call == "retire_scan_ingress")
                .count(),
            1,
            "callback retirement is not repeated after it succeeded"
        );
        assert_eq!(
            calls
                .iter()
                .filter(|call| *call == "fence_scan_ingress")
                .count(),
            2,
            "only the refused fence is retried"
        );
        assert!(!central.has_active_scan().await);
    }

