    #[tokio::test]
    async fn scoped_old_generation_cannot_mutate_new_link() {
        let central = open().await;
        central
            .boundary()
            .push_event(advertisement("scoped-peer"))
            .expect("synthetic event admission failed");
        let old = central
            .connect("scoped-peer", "lease-a", OpControl::unbounded())
            .await
            .expect("initial connection");
        let old_generation = old
            .connection_generation
            .clone()
            .expect("initial connection generation");
        super::reconcile_disconnected(&central.inner, "scoped-peer", true).await;
        let current = central
            .connect("scoped-peer", "lease-b", OpControl::unbounded())
            .await
            .expect("replacement connection");
        let current_generation = current
            .connection_generation
            .clone()
            .expect("replacement connection generation");
        assert_ne!(old_generation, current_generation);
        let before_epoch = central
            .inner
            .epochs
            .lock()
            .await
            .get("scoped-peer")
            .copied()
            .unwrap_or(0);
        super::reconcile_connected_scoped(&central.inner, "scoped-peer", Some(&old_generation))
            .await;
        super::reconcile_disconnected_scoped(
            &central.inner,
            "scoped-peer",
            true,
            None,
            Some(&old_generation),
        )
        .await;

        assert_eq!(
            central
                .with_core(|core| core.connection_state(&current.peer_key))
                .await,
            Some(ConnectionState::Connected),
            "stale connected/lost events cannot change replacement state"
        );
        assert_eq!(
            central
                .inner
                .epochs
                .lock()
                .await
                .get("scoped-peer")
                .copied()
                .unwrap_or(0),
            before_epoch,
            "stale loss cannot invalidate replacement routing"
        );
        central.shutdown().await;
    }

    #[tokio::test]
    async fn connect_shares_live_link_by_default() {
        // FX1B: sharing is the default — a second connect leases the live
        // link instead of failing `connection.already-owned`.
        let central = open().await;
        central
            .boundary()
            .push_event(advertisement("peer-1"))
            .expect("synthetic event admission failed");
        let handle = central
            .connect("peer-1", "lease-a", OpControl::budget_ms(5000))
            .await
            .expect("connect");
        assert!(!handle.peer_key.is_empty());
        assert!(handle.connection_generation.is_some());
        let state = central
            .with_core(|core| core.connection_state(&handle.peer_key))
            .await;
        assert_eq!(state, Some(ConnectionState::Connected));
        let joined = central
            .connect("peer-1", "lease-b", OpControl::budget_ms(5000))
            .await
            .expect("second lease joins the live link");
        assert_eq!(
            joined.connection_generation, handle.connection_generation,
            "one link, one link generation, two leases"
        );
        let leases = central
            .with_core(|core| core.connection_lease_count(&handle.peer_key))
            .await;
        assert_eq!(leases, 2, "two leases on the shared link");
        central
            .disconnect("peer-1", "lease-a", OpControl::unbounded())
            .await
            .expect("disconnect");
        let state = central
            .with_core(|core| core.connection_state(&handle.peer_key))
            .await;
        assert_eq!(state, Some(ConnectionState::Disconnected));
    }

