        assert_eq!(failure.code(), BleErrorCode::OperationTimedOut);
        assert!(ticket.is_settled());
        let next = OpControl::budget_ms(5000)
            .with_gatt_admission(central.admit_gatt("ready-peer").unwrap());
        drop(earlier);
