        let pending = central
            .unsubscribe(peer, &selector, "consumer", OpControl::unbounded())
            .await
            .unwrap_err();
        assert_eq!(pending.operation(), "gatt.unsubscribe.settlement");
        assert!(!central.shutdown().await.is_released());
        let calls = central
            .boundary()
            .calls()
            .iter()
            .filter(|call| *call == "set_notifications")
            .count();
